	}

	local function decodeVal(value)
		if type(value) ~= "table" then return value end
		local kind = value[1]
		if kind == 1 then return Color3.new(value[2], value[3], value[4]) end
		if kind == 2 then return Vector3.new(value[2], value[3], value[4]) end
		if kind == 3 then return Vector2.new(value[2], value[3]) end
		if kind == 4 then return NumberRange.new(value[2], value[3]) end
		if kind == 5 then
			local pts = {}
			for idx = 2, #value, 3 do
				table.insert(pts, NumberSequenceKeypoint.new(value[idx], value[idx + 1], value[idx + 2]))
			end
			return NumberSequence.new(pts)
		end
		if kind == 6 then
			local pts = {}
			for idx = 2, #value, 4 do
				table.insert(pts, ColorSequenceKeypoint.new(value[idx], Color3.new(value[idx + 1], value[idx + 2], value[idx + 3])))
			end
			return ColorSequence.new(pts)
		end
		if kind == 7 then return CFrame.new(unpack(value, 2, 13)) end
		if kind == 8 then
			local name = tostring(value[2]):gsub("^Enum%.", "")
			local ok, item = pcall(function() return Enum[name][value[3]] end)
			return ok and item or nil
		end
		return nil
	end

	local function clearAura(char)
		if not char then return end
		for _, d in ipairs(char:GetDescendants()) do
			if d:GetAttribute("PulseVFX") == true or d.Name == "CH_WhiteSparkAura" then
				pcall(function() d:Destroy() end)
			end
		end
	end

	local function buildNode(data, parent, build)
		local cls = AURA_CLASSES[data.c]
		if not cls then return nil end
		local obj = Instance.new(cls)
		obj.Name = data.n or cls
		if data.p then
			for prop, val in pairs(data.p) do
				pcall(function() obj[prop] = decodeVal(val) end)
			end
		end
		-- Vücuda tam kilitli olması için karakterle birlikte hareket etsin, arkada kalmasın
		if data.c == "P" then
			obj.LockedToPart = true
		elseif data.c == "T" then
			obj.Lifetime = math.min(obj.Lifetime, 0.25)
		end
		if data.i then build.ids[data.i] = obj end
		if data.a or data.b then table.insert(build.links, { obj, data.a, data.b }) end
		obj:SetAttribute("PulseVFX", true)
		if data.k then
			for _, child in ipairs(data.k) do
				buildNode(child, obj, build)
			end
		end
		obj.Parent = parent
		return obj
	end

	local function resolveBodyHost(char, hostName)
		local direct = char:FindFirstChild(hostName)
		if direct and direct:IsA("BasePart") and hostName ~= "HumanoidRootPart" then
			return direct
		end
		local mappedName = R15_MAP[hostName]
		if mappedName then
			local mapped = char:FindFirstChild(mappedName)
			if mapped and mapped:IsA("BasePart") then return mapped end
		end
		return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
	end

	local function applyAuraKey(char, key)
		local data = AURA_DATA[key]
		if not data then return end
		local build = { ids = {}, links = {} }
		for _, hostData in ipairs(data.h or {}) do
			local host = resolveBodyHost(char, hostData.n)
			if host then
				for _, child in ipairs(hostData.k or {}) do
					buildNode(child, host, build)
				end
			end
		end
		for _, lnk in ipairs(build.links) do
			pcall(function()
				if lnk[2] and build.ids[lnk[2]] then lnk[1].Attachment0 = build.ids[lnk[2]] end
				if lnk[3] and build.ids[lnk[3]] then lnk[1].Attachment1 = build.ids[lnk[3]] end
			end)
		end
	end

	applyAuras = function()
		local char = player.Character
		if not char then return end
		clearAura(char)
		if ZX.aura.whiteSpark then pcall(applyAuraKey, char, "pa_whitespark") end
		if ZX.aura.ultraInstinct then pcall(applyAuraKey, char, "pa_mui") end
	end

	player.CharacterAdded:Connect(function(newChar)
		newChar:WaitForChild("HumanoidRootPart", 8)
		task.wait(0.6)
		if ZX.aura.whiteSpark or ZX.aura.ultraInstinct then
			pcall(applyAuras)
		end
	end)
end


-- =========================================================================
-- 6.2) CHARACTER COSMETICS — KORBLOX & HEADLESS (R6 + R15, Reset Kalıcı)
-- =========================================================================
local applyKorblox
local applyHeadless
do
	local KOR_MESH = "rbxassetid://9598310133"
	local KOR_TEX  = "rbxassetid://902843398"
	local legSaved, extras, legacyMesh = {}, {}, nil
	local headSaved = {}

	local function restoreLeg()
		for _, o in ipairs(extras) do pcall(function() o:Destroy() end) end
		extras = {}
		for part, orig in pairs(legSaved) do
			pcall(function()
				if orig.MeshId ~= nil then part.MeshId = orig.MeshId end
				if orig.TextureID ~= nil then part.TextureID = orig.TextureID end
				if orig.Transparency ~= nil then part.Transparency = orig.Transparency end
			end)
		end
		legSaved = {}
		if legacyMesh then
			pcall(function() legacyMesh:Destroy() end)
			legacyMesh = nil
		end
	end

	local function hideLeg(part)
		if not part then return end
		pcall(function()
			legSaved[part] = legSaved[part] or {}
			if legSaved[part].Transparency == nil then legSaved[part].Transparency = part.Transparency end
			part.Transparency = 1
		end)
	end

	local function replaceLeg(part)
		if not part then return end
		local replaced = false
		pcall(function()
			legSaved[part] = { MeshId = part.MeshId, TextureID = part.TextureID, Transparency = part.Transparency }
			part.MeshId = KOR_MESH
			part.TextureID = KOR_TEX
			replaced = (part.MeshId == KOR_MESH)
		end)
		if replaced then return end
		pcall(function()
			local obj = Instance.new("Part")
			obj.Name = "CH_KorbloxLeg"
			obj.Size = Vector3.new(1, 1, 1)
			obj.CanCollide = false
			obj.CanQuery = false
			obj.CanTouch = false
			obj.Massless = true
			obj.Anchored = false
			obj.Transparency = 0
			local sm = Instance.new("SpecialMesh")
			sm.MeshType = Enum.MeshType.FileMesh
			sm.MeshId = KOR_MESH
			sm.TextureId = KOR_TEX
			sm.Scale = Vector3.new(1, 1, 1)
			sm.Parent = obj
			obj.CFrame = part.CFrame
			obj.Parent = part
			local w = Instance.new("Weld")
			w.Part0 = part
			w.Part1 = obj
			w.C0 = CFrame.new()
			w.Parent = obj
			table.insert(extras, obj)
			part.Transparency = 1
		end)
	end

	applyKorblox = function(enabled)
		ZX.character.korblox = enabled == true
		restoreLeg()
		if not ZX.character.korblox then return end
		local char = player.Character
		if not char then return end
		local lower = char:FindFirstChild("RightLowerLeg")
		if lower then
			replaceLeg(char:FindFirstChild("RightUpperLeg"))
			hideLeg(lower)
			hideLeg(char:FindFirstChild("RightFoot"))
		else
			local leg = char:FindFirstChild("Right Leg")
			if leg then
				local oldSm = leg:FindFirstChildOfClass("SpecialMesh")
				if oldSm then oldSm:Destroy() end
				legacyMesh = Instance.new("SpecialMesh")
				legacyMesh.MeshType = Enum.MeshType.FileMesh
				legacyMesh.MeshId = KOR_MESH
				legacyMesh.TextureId = KOR_TEX
				legacyMesh.Parent = leg
			end
		end
	end

	local function restoreHead()
		for obj, trans in pairs(headSaved) do
			pcall(function() obj.Transparency = trans end)
		end
		headSaved = {}
	end

	applyHeadless = function(enabled)
		ZX.character.headless = enabled == true
		restoreHead()
		if not ZX.character.headless then return end
		local char = player.Character
		local head = char and char:FindFirstChild("Head")
		if not head then return end
		pcall(function()
			headSaved[head] = head.Transparency
			head.Transparency = 1
		end)
		for _, d in ipairs(char:GetDescendants()) do
			if d:IsA("Decal") and d.Name == "face" then
				pcall(function()
					headSaved[d] = d.Transparency
					d.Transparency = 1
				end)
			end
		end
	end

	player.CharacterAdded:Connect(function(newChar)
		newChar:WaitForChild("Head", 8)
		task.wait(0.6)
		legSaved, extras, legacyMesh, headSaved = {}, {}, nil, {}
		if ZX.character.korblox then pcall(applyKorblox, true) end
		if ZX.character.headless then pcall(applyHeadless, true) end
	end)
end

