local SKYBOX_BY_NAME = {}
local SKYBOX_NAMES = { "Default" }
for _, entry in ipairs(SKYBOX_CATALOG) do
	SKYBOX_BY_NAME[entry.name] = entry
	table.insert(SKYBOX_NAMES, entry.name)
end

local _originalSky = nil

local function ApplySkybox(name)
	local Lighting = game:GetService("Lighting")
	local prev = Lighting:FindFirstChild("ZeroX_Sky")
	if prev then
		pcall(function() prev:Destroy() end)
	end
	local curSky = Lighting:FindFirstChildOfClass("Sky")
	if curSky and curSky.Name ~= "ZeroX_Sky" then
		_originalSky = curSky
	end

	if not name or name == "Default" or not SKYBOX_BY_NAME[name] then
		ZX.skybox.selected = "Default"
		if _originalSky and not _originalSky.Parent then
			pcall(function() _originalSky.Parent = Lighting end)
		end
		return
	end

	if _originalSky and _originalSky.Parent == Lighting then
		pcall(function() _originalSky.Parent = nil end)
	end

	local spec = SKYBOX_BY_NAME[name]
	local sky = Instance.new("Sky")
	sky.Name = "ZeroX_Sky"
	sky.SkyboxBk = "rbxassetid://" .. tostring(spec.faces[1])
	sky.SkyboxDn = "rbxassetid://" .. tostring(spec.faces[2])
	sky.SkyboxFt = "rbxassetid://" .. tostring(spec.faces[3])
	sky.SkyboxLf = "rbxassetid://" .. tostring(spec.faces[4])
	sky.SkyboxRt = "rbxassetid://" .. tostring(spec.faces[5])
	sky.SkyboxUp = "rbxassetid://" .. tostring(spec.faces[6])
	sky.CelestialBodiesShown = spec.celestial == true
	sky.StarCount = spec.stars or 3000
	sky.SunAngularSize = spec.sun or 21
	sky.MoonAngularSize = spec.moon or 11
	if spec.sunTex ~= nil then sky.SunTextureId = spec.sunTex end
	if spec.moonTex ~= nil then sky.MoonTextureId = spec.moonTex end
	sky.Parent = Lighting
	ZX.skybox.selected = name
end

