local GAZER_ANIM_CATS = { "Idle", "Walk", "Run", "Jump", "Fall", "Swim", "SwimIdle", "Climb" }
local GAZER_ANIM_NAMES = {}
for _, cat in ipairs(GAZER_ANIM_CATS) do
	local list = { "Default" }
	local tmp = {}
	for name in pairs(GAZER_ANIMS[cat]) do
		table.insert(tmp, name)
	end
	table.sort(tmp)
	for _, name in ipairs(tmp) do
		table.insert(list, name)
	end
	GAZER_ANIM_NAMES[cat] = list
end

local ApplyFEAnimation
local ResetAllFEAnimations
do
	local _origAnimateRef = nil
	local _origAnimIds = {}

	local function captureOrig(Animate)
		if _origAnimateRef == Animate then return end
		_origAnimateRef = Animate
		_origAnimIds = {}
		pcall(function()
			if Animate:FindFirstChild("idle") and Animate.idle:FindFirstChild("Animation1") and Animate.idle:FindFirstChild("Animation2") then
				_origAnimIds.Idle = { Animate.idle.Animation1.AnimationId, Animate.idle.Animation2.AnimationId }
			end
			if Animate:FindFirstChild("walk") and Animate.walk:FindFirstChild("WalkAnim") then
				_origAnimIds.Walk = Animate.walk.WalkAnim.AnimationId
			end
			if Animate:FindFirstChild("run") and Animate.run:FindFirstChild("RunAnim") then
				_origAnimIds.Run = Animate.run.RunAnim.AnimationId
			end
			if Animate:FindFirstChild("jump") and Animate.jump:FindFirstChild("JumpAnim") then
				_origAnimIds.Jump = Animate.jump.JumpAnim.AnimationId
			end
			if Animate:FindFirstChild("fall") and Animate.fall:FindFirstChild("FallAnim") then
				_origAnimIds.Fall = Animate.fall.FallAnim.AnimationId
			end
			if Animate:FindFirstChild("swim") and Animate.swim:FindFirstChild("Swim") then
				_origAnimIds.Swim = Animate.swim.Swim.AnimationId
			end
			if Animate:FindFirstChild("swimidle") and Animate.swimidle:FindFirstChild("SwimIdle") then
				_origAnimIds.SwimIdle = Animate.swimidle.SwimIdle.AnimationId
			end
			if Animate:FindFirstChild("climb") and Animate.climb:FindFirstChild("ClimbAnim") then
				_origAnimIds.Climb = Animate.climb.ClimbAnim.AnimationId
			end
		end)
	end

	local function stopTracks(Hum)
		if not Hum then return end
		pcall(function()
			for _, tr in ipairs(Hum:GetPlayingAnimationTracks()) do
				tr:Stop(0)
			end
		end)
	end

	local function toUrl(id)
		local s = tostring(id)
		if s:find("asset") or s:find("rbxassetid") then return s end
		return "http://www.roblox.com/asset/?id=" .. s
	end

	ApplyFEAnimation = function(cat, name)
		if not GAZER_ANIMS[cat] then return end
		if not name or name == "Default" or not GAZER_ANIMS[cat][name] then
			ZX.animations[cat] = "Default"
		else
			ZX.animations[cat] = name
		end

		local char = player.Character
		if not char then return end
		local Hum = char:FindFirstChildOfClass("Humanoid")
		local Animate = char:FindFirstChild("Animate")
		if not Hum or not Animate then return end

		captureOrig(Animate)
		stopTracks(Hum)

		local val = (ZX.animations[cat] ~= "Default") and GAZER_ANIMS[cat][ZX.animations[cat]] or _origAnimIds[cat]
		if not val then return end

		pcall(function()
			if cat == "Idle" and Animate:FindFirstChild("idle") then
				local a1 = Animate.idle:FindFirstChild("Animation1")
				local a2 = Animate.idle:FindFirstChild("Animation2")
				if a1 and a2 and type(val) == "table" then
					a1.AnimationId = "http://www.roblox.com/asset/?id=0"
					a2.AnimationId = "http://www.roblox.com/asset/?id=0"
					a1.AnimationId = toUrl(val[1])
					a2.AnimationId = toUrl(val[2])
				end
				Hum:ChangeState(Enum.HumanoidStateType.Freefall)
			elseif cat == "Walk" and Animate:FindFirstChild("walk") and Animate.walk:FindFirstChild("WalkAnim") then
				Animate.walk.WalkAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				Animate.walk.WalkAnim.AnimationId = toUrl(val)
				Hum:ChangeState(Enum.HumanoidStateType.Freefall)
			elseif cat == "Run" and Animate:FindFirstChild("run") and Animate.run:FindFirstChild("RunAnim") then
				Animate.run.RunAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				Animate.run.RunAnim.AnimationId = toUrl(val)
				Hum:ChangeState(Enum.HumanoidStateType.Freefall)
			elseif cat == "Jump" and Animate:FindFirstChild("jump") and Animate.jump:FindFirstChild("JumpAnim") then
				Animate.jump.JumpAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				Animate.jump.JumpAnim.AnimationId = toUrl(val)
				Hum:ChangeState(Enum.HumanoidStateType.Freefall)
			elseif cat == "Fall" and Animate:FindFirstChild("fall") and Animate.fall:FindFirstChild("FallAnim") then
				Animate.fall.FallAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				Animate.fall.FallAnim.AnimationId = toUrl(val)
				Hum:ChangeState(Enum.HumanoidStateType.Freefall)
			elseif cat == "Swim" and Animate:FindFirstChild("swim") and Animate.swim:FindFirstChild("Swim") then
				Animate.swim.Swim.AnimationId = "http://www.roblox.com/asset/?id=0"
				Animate.swim.Swim.AnimationId = toUrl(val)
				Hum:ChangeState(Enum.HumanoidStateType.GettingUp)
				task.delay(0.05, function() pcall(function() Hum:ChangeState(Enum.HumanoidStateType.Swimming) end) end)
			elseif cat == "SwimIdle" and Animate:FindFirstChild("swimidle") and Animate.swimidle:FindFirstChild("SwimIdle") then
				Animate.swimidle.SwimIdle.AnimationId = "http://www.roblox.com/asset/?id=0"
				Animate.swimidle.SwimIdle.AnimationId = toUrl(val)
				Hum:ChangeState(Enum.HumanoidStateType.GettingUp)
				task.delay(0.05, function() pcall(function() Hum:ChangeState(Enum.HumanoidStateType.Swimming) end) end)
			elseif cat == "Climb" and Animate:FindFirstChild("climb") and Animate.climb:FindFirstChild("ClimbAnim") then
				Animate.climb.ClimbAnim.AnimationId = "http://www.roblox.com/asset/?id=0"
				Animate.climb.ClimbAnim.AnimationId = toUrl(val)
				Hum:ChangeState(Enum.HumanoidStateType.GettingUp)
				task.delay(0.05, function() pcall(function() Hum:ChangeState(Enum.HumanoidStateType.Climbing) end) end)
			end
		end)
	end

	ResetAllFEAnimations = function()
		for _, cat in ipairs(GAZER_ANIM_CATS) do
			ZX.animations[cat] = "Default"
			pcall(ApplyFEAnimation, cat, "Default")
		end
	end

	player.CharacterAdded:Connect(function(char)
		_origAnimateRef = nil
		_origAnimIds = {}
		local anim = char:WaitForChild("Animate", 8)
		if not anim then return end
		task.wait(0.25)
		captureOrig(anim)
		for _, cat in ipairs(GAZER_ANIM_CATS) do
			if ZX.animations[cat] and ZX.animations[cat] ~= "Default" then
				pcall(ApplyFEAnimation, cat, ZX.animations[cat])
			end
		end
	end)
end

