	local pulseSkinsDB = {}
	pcall(function()
		local decoded = HttpService:JSONDecode(MM2_SKINS_JSON)
		if type(decoded) == "table" then pulseSkinsDB = decoded end
	end)

	for k, info in pairs(pulseSkinsDB) do
		if type(info) == "table" and (info.t == "Knife" or info.t == "Gun") and info.d then
			local nid = extractNumericId(info.img)
			local raw = {
				key = k,
				name = info.nm or k,
				rarity = info.r or "Common",
				id = nid,
				img = info.img,
				grip = info.g,
				dbEntry = info,
			}
			if info.t == "Knife" then
				registerEntry(skinCatalogData.Knives, seenK, raw)
			else
				registerEntry(skinCatalogData.Guns, seenG, raw)
			end
		end
	end

	for _, e in ipairs(BUILTIN_KNIVES) do registerEntry(skinCatalogData.Knives, seenK, e) end
	for _, e in ipairs(BUILTIN_GUNS) do registerEntry(skinCatalogData.Guns, seenG, e) end

	local function sortList(list)
		table.sort(list, function(a, b)
			local ra = RARITY_ORDER[a.rarity] or 9
			local rb = RARITY_ORDER[b.rarity] or 9
			if ra ~= rb then return ra < rb end
			return tostring(a.name):lower() < tostring(b.name):lower()
		end)
	end
	sortList(skinCatalogData.Knives)
	sortList(skinCatalogData.Guns)

	local origSnap = {}
	local function snapshotTool(tool)
		if origSnap[tool] then return end
		local h = tool:FindFirstChild("Handle") or tool:FindFirstChildWhichIsA("BasePart")
		if not h then return end
		local mesh = h:FindFirstChildOfClass("SpecialMesh")
		origSnap[tool] = {
			grip = tool.Grip,
			tex  = tool.TextureId,
			meshId = (h:IsA("MeshPart") and h.MeshId) or (mesh and mesh.MeshId) or "",
			meshTex = (h:IsA("MeshPart") and h.TextureID) or (mesh and mesh.TextureId) or "",
			scale = mesh and mesh.Scale or Vector3.new(1, 1, 1),
		}
	end

	local skinMeshCache = {}
	local skinLoading = {}

	local function decodeSkinVal(value)
		if type(value) ~= "table" then return value end
		local kind = value[1]
		if kind == "V" then return Vector3.new(value[2], value[3], value[4]) end
		if kind == "C" then return Color3.new(value[2], value[3], value[4]) end
		if kind == "F" then return CFrame.new(unpack(value, 2, 13)) end
		if kind == "NR" then return NumberRange.new(value[2], value[3]) end
		if kind == "E" then
			local ok, item = pcall(function() return Enum[value[2]][value[3]] end)
			return ok and item or nil
		end
		if kind == "CS" then
			local pts = {}
			for i = 2, #value do
				local p = value[i]
				table.insert(pts, ColorSequenceKeypoint.new(p[1], Color3.new(p[2], p[3], p[4])))
			end
			local ok, seq = pcall(ColorSequence.new, pts)
			return ok and seq or nil
		end
		if kind == "NS" then
			local pts = {}
			for i = 2, #value do
				local p = value[i]
				table.insert(pts, NumberSequenceKeypoint.new(p[1], p[2], p[3] or 0))
			end
			local ok, seq = pcall(NumberSequence.new, pts)
			return ok and seq or nil
		end
		return nil
	end

	local function createCachedMeshPart(meshId)
		if skinMeshCache[meshId] then return skinMeshCache[meshId]:Clone() end
		while skinLoading[meshId] do task.wait() end
		if skinMeshCache[meshId] then return skinMeshCache[meshId]:Clone() end
		skinLoading[meshId] = true
		local ok, res = pcall(function()
			return InsertService:CreateMeshPartAsync(meshId, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Automatic)
		end)
		skinLoading[meshId] = nil
		if ok and res then
			skinMeshCache[meshId] = res
			return res:Clone()
		end
		-- CreateMeshPartAsync desteklenmiyorsa Part + SpecialMesh fallback
		local p = Instance.new("Part")
		p.Size = Vector3.new(1, 1, 1)
		local sm = Instance.new("SpecialMesh")
		sm.MeshType = Enum.MeshType.FileMesh
		sm.MeshId = meshId
		sm.Parent = p
		return p
	end

	local function buildSkinNode(data, root, refs, unres)
		local obj
		if data.c == "MeshPart" then
			obj = createCachedMeshPart((data.p and data.p.MeshId) or "")
		end
		if not obj then
			local ok, created = pcall(Instance.new, data.c)
			if not ok or not created then return nil end
			obj = created
		end
		obj.Name = data.n or data.c
		if data.p then
			for prop, val in pairs(data.p) do
				if not (prop == "MeshId" and data.c == "MeshPart") then
					if type(val) == "table" and val[1] == "R" then
						table.insert(unres, { obj, prop, val[2] })
					else
						local dec = decodeSkinVal(val)
						if dec ~= nil then
							pcall(function() obj[prop] = dec end)
							if obj:IsA("Part") and prop == "TextureID" then
								local sm = obj:FindFirstChildOfClass("SpecialMesh")
								if sm then sm.TextureId = dec end
							end
						end
					end
				end
			end
		end
		if data.i then refs[data.i] = obj end
		if obj:IsA("BasePart") then
			obj.Anchored = false
			obj.CanCollide = false
			obj.CanQuery = false
			obj.CanTouch = false
			obj.Massless = true
			pcall(function() obj.AudioCanCollide = false end)
			if root and data.r then
				local w = Instance.new("Weld")
				w.Name = "PW"
				w.Part0 = root
				w.Part1 = obj
				w.C0 = CFrame.new(unpack(data.r, 1, 12))
				w.Parent = obj
			end
		end
		if data.a then
			for k, v in pairs(data.a) do pcall(obj.SetAttribute, obj, k, decodeSkinVal(v)) end
		end
		if data.t then
			for _, tag in ipairs(data.t) do pcall(CollectionService.AddTag, CollectionService, obj, tag) end
		end
		local parentRoot = root or (obj:IsA("BasePart") and obj) or nil
		if data.k then
			for _, child in ipairs(data.k) do
				local built = buildSkinNode(child, parentRoot, refs, unres)
				if built then
					built.Parent = obj
					if not parentRoot and built:IsA("BasePart") then parentRoot = built end
				end
			end
		end
		return obj
	end

	local function buildSkinModel(dbEntry)
		if not (dbEntry and dbEntry.d) then return nil end
		local refs, unres = {}, {}
		local rootObj = buildSkinNode(dbEntry.d, nil, refs, unres)
		if not rootObj then return nil end
		for _, r in ipairs(unres) do
			local target = refs[r[3]]
			if target then pcall(function() r[1][r[2]] = target end) end
		end
		if dbEntry.ch then
			for _, o in ipairs(rootObj:GetDescendants()) do
				if o:IsA("Decal") and o.Name:lower():find("chroma") then pcall(CollectionService.AddTag, CollectionService, o, "ChromaDecal") end
				if o:IsA("Fire") then pcall(CollectionService.AddTag, CollectionService, o, "ChromaFire") end
			end
		end
		return rootObj
	end

	local function applyMeshToHandle(h, entry)
		if not h or not h:IsA("BasePart") then return end
		local oldVis = h:FindFirstChild("CH_SkinVisual")
		if oldVis then oldVis:Destroy() end

		if not entry or not ZX.skins.enabled then
			if h:GetAttribute("CH_OrigTrans") ~= nil then
				h.Transparency = h:GetAttribute("CH_OrigTrans")
			end
			return
		end

		if entry.dbEntry then
			if h:GetAttribute("CH_OrigTrans") == nil then
				h:SetAttribute("CH_OrigTrans", h.Transparency)
			end
			h.Transparency = 1
			local built = buildSkinModel(entry.dbEntry)
			if built then
				built.Name = "CH_SkinVisual"
				local primary = built:IsA("BasePart") and built or built:FindFirstChildWhichIsA("BasePart", true)
				if primary then
					primary.CFrame = h.CFrame
					local w = Instance.new("Weld")
					w.Part0 = h
					w.Part1 = primary
					w.C0 = CFrame.new()
					w.Parent = primary
				end
				built.Parent = h
			end
			return
		end

		local meshId, texId = entry.mesh, entry.tex
		if not meshId or meshId == "" then return end
		local scaleVec = entry.scale and Vector3.new(entry.scale[1], entry.scale[2], entry.scale[3]) or Vector3.new(1, 1, 1)
		if h:GetAttribute("CH_OrigTrans") == nil then
			h:SetAttribute("CH_OrigTrans", h.Transparency)
		end
		if h:IsA("MeshPart") then
			h.Transparency = 1
			local vis = Instance.new("Part")
			vis.Name = "CH_SkinVisual"
			vis.Size = h.Size
			vis.Anchored = false
			vis.CanCollide = false
			vis.CanQuery = false
			vis.CanTouch = false
			vis.Massless = true
			vis.CFrame = h.CFrame
			local sm = Instance.new("SpecialMesh")
			sm.MeshType = Enum.MeshType.FileMesh
			sm.MeshId = meshId
			if texId then sm.TextureId = texId end
			sm.Scale = scaleVec
			sm.Parent = vis
			local w = Instance.new("WeldConstraint")
			w.Part0 = h
			w.Part1 = vis
			w.Parent = vis
			vis.Parent = h
		else
			local m = h:FindFirstChildOfClass("SpecialMesh")
			if not m then
				m = Instance.new("SpecialMesh")
				m.Parent = h
			end
			m.MeshType = Enum.MeshType.FileMesh
			m.MeshId = meshId
			if texId then m.TextureId = texId end
			m.Scale = scaleVec
		end
	end

	local function applyToTool(tool, entry)
		if not tool or not tool:IsA("Tool") then return end
		snapshotTool(tool)
		local h = tool:FindFirstChild("Handle") or tool:FindFirstChildWhichIsA("BasePart")
		if not h then return end

		if not entry or not ZX.skins.enabled then
			applyMeshToHandle(h, nil)
			local sn = origSnap[tool]
			if sn then
				pcall(function()
					tool.Grip = sn.grip
					tool.TextureId = sn.tex
					local m = h:FindFirstChildOfClass("SpecialMesh")
					if m then
						m.MeshId = sn.meshId
						m.TextureId = sn.meshTex
						m.Scale = sn.scale
					end
				end)
			end
			return
		end

		pcall(function()
			applyMeshToHandle(h, entry)
			if entry.image and entry.image ~= "" then
				tool.TextureId = entry.image
			end
			if entry.grip then
				tool.Grip = CFrame.new(unpack(entry.grip))
			end
		end)
	end

	-- Karakterin üstündeki (belindeki/sırtındaki) takılı bıçak ve silah modellerini de güncelle
	local function applyHolsteredOnChar(char)
		if not char then return end
		for _, obj in ipairs(char:GetChildren()) do
			if not obj:IsA("Tool") then
				local ln = obj.Name:lower()
				local kind = nil
				if ln:find("knife") then kind = "Knife"
				elseif ln:find("gun") or ln:find("revolver") then kind = "Gun" end
				if kind then
					local entry = (kind == "Knife") and ZX.skins.knife or ZX.skins.gun
					local h = obj:IsA("BasePart") and obj or obj:FindFirstChild("Handle") or obj:FindFirstChildWhichIsA("BasePart")
					if h then pcall(applyMeshToHandle, h, entry) end
				end
			end
		end
	end

	applyWeaponSkin = function(kind, entryOrKey)
		local entry = type(entryOrKey) == "string" and skinCatalogData.ByKey[entryOrKey] or entryOrKey
		if kind == "Knife" then ZX.skins.knife = entry else ZX.skins.gun = entry end
		local char = player.Character
		local bp = player:FindFirstChild("Backpack")
		for _, holder in ipairs({ char, bp }) do
			if holder then
				for _, t in ipairs(holder:GetChildren()) do
					if t:IsA("Tool") and weaponKind(t) == kind then
						applyToTool(t, entry)
					end
				end
			end
		end
		if char then pcall(applyHolsteredOnChar, char) end
	end

	task.spawn(function()
		while true do
			pcall(function()
				if ZX.skins.enabled then
					local char = player.Character
					local bp = player:FindFirstChild("Backpack")
					for _, holder in ipairs({ char, bp }) do
						if holder then
							for _, t in ipairs(holder:GetChildren()) do
								if t:IsA("Tool") then
									local k = weaponKind(t)
									if k == "Knife" and ZX.skins.knife then
										applyToTool(t, ZX.skins.knife)
									elseif k == "Gun" and ZX.skins.gun then
										applyToTool(t, ZX.skins.gun)
									end
								end
							end
						end
					end
					if char then applyHolsteredOnChar(char) end
				end
			end)
			task.wait(0.8)
		end
	end)
end

