				})

				local tap = new("ImageButton", {
					Name = rnd(),
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.new(1, -3, 0.5, 0),
					Size = UDim2.fromOffset(32, 22),
					BackgroundTransparency = 1,
