	-- GRUP 3: SETTINGS -> CONFIG + DATA
	local SettingsGroup = Window:AddGroup("SETTINGS", "settings", {
		{ Icon = "sliders-horizontal", Name = "Config" },
		{ Icon = "info", Name = "Data" },
	})

	local loaderData = nil
	pcall(function()
		local g = (type(getgenv) == "function" and getgenv()) or _G
		if type(g) == "table" and type(g.CelestialLoaderData) == "table" then
			loaderData = g.CelestialLoaderData
		end
	end)

	do
		local execName = (loaderData and type(loaderData.executor) == "string" and loaderData.executor ~= "" and loaderData.executor) or "Unknown"
		pcall(function()
			if type(identifyexecutor) == "function" then
				local n, v = identifyexecutor()
				if type(n) == "string" and n ~= "" then
					execName = (type(v) == "string" and v ~= "") and (n .. " (" .. v .. ")") or n
				end
			elseif type(getexecutorname) == "function" then
				local n = getexecutorname()
				if type(n) == "string" and n ~= "" then execName = n end
			end
		end)

		local execIdentity = (loaderData and type(loaderData.identity) == "string" and loaderData.identity ~= "" and loaderData.identity) or "Unknown"
		pcall(function()
			if type(getthreadidentity) == "function" then
				execIdentity = tostring(getthreadidentity())
			elseif type(getidentity) == "function" then
				execIdentity = tostring(getidentity())
			elseif type(syn) == "table" and type(syn.get_thread_identity) == "function" then
				execIdentity = tostring(syn.get_thread_identity())
			end
		end)

		local dataSec = SettingsGroup.Data:AddSection({ Name = "Executor Data", Position = "left" })
		dataSec:AddLabel("Executor: " .. execName, true)
		dataSec:AddLabel("Identity: Level " .. execIdentity, true)
	end

	do
		local uid = (loaderData and loaderData.userId) or (player and player.UserId) or 0
		local CFG_DIR = "CelestialHub/users/" .. tostring(uid)
		local selectedConfig = "default"
		local typedName = "default"
		local HttpService = game:GetService("HttpService")

		local function ensureDir()
			pcall(function()
				if type(makefolder) == "function" then
					makefolder("CelestialHub")
					makefolder("CelestialHub/users")
					makefolder(CFG_DIR)
				end
			end)
		end

		local function sanitizeName(n)
			n = tostring(n or ""):gsub("[^%w_%-%s]", ""):gsub("^%s+", ""):gsub("%s+$", "")
			if n == "" then return "default" end
			return n
		end

		local INDEX_PATH = CFG_DIR .. "/_index.json"

		local function readConfigIndex()
			local out = {}
			if type(readfile) == "function" and type(isfile) == "function" then
				local okHas, has = pcall(isfile, INDEX_PATH)
				if okHas and has then
					local okR, raw = pcall(readfile, INDEX_PATH)
					if okR and type(raw) == "string" then
						local okJ, arr = pcall(function() return HttpService:JSONDecode(raw) end)
						if okJ and type(arr) == "table" then
							for _, v in ipairs(arr) do
								if type(v) == "string" and v ~= "" then table.insert(out, v) end
							end
						end
					end
				end
			end
			return out
		end

		local function writeConfigIndex(list)
			if type(writefile) == "function" then
				ensureDir()
				pcall(writefile, INDEX_PATH, HttpService:JSONEncode(list))
			end
		end

		local function listSavedConfigs()
			local out = readConfigIndex()
			ensureDir()
			if loaderData and type(loaderData.configs) == "table" then
				for k, _ in pairs(loaderData.configs) do
					local found = false
					for _, ex in ipairs(out) do if ex == k then found = true break end end
					if not found then table.insert(out, k) end
				end
			end
			if #out == 0 then table.insert(out, "default") end
			return out
		end

		local function collectConfig()
			return {
				esp = {
					enabled = ZX.esp.enabled, box = ZX.esp.box, skeleton = ZX.esp.skeleton,
					names = ZX.esp.names, murderer = ZX.esp.murderer, sheriff = ZX.esp.sheriff, innocent = ZX.esp.innocent,
				},
				hitbox = {
					enabled = ZX.hitbox.enabled, size = ZX.hitbox.size, transparency = ZX.hitbox.transparency,
				},
				combat = {
					wallbang = ZX.combat.wallbang, autoGrabGun = ZX.combat.autoGrabGun,
					shootKey = ZX.combat.shootKey and ZX.combat.shootKey.Name or nil, killAura = ZX.combat.killAura,
					spinbot = ZX.combat.spinbot, spinSpeed = ZX.combat.spinSpeed, revealRoles = ZX.combat.revealRoles,
				},
				farm = {
					enabled = ZX.farm.enabled, mode = ZX.farm.mode, speed = ZX.farm.speed,
					delay = ZX.farm.delay, coinType = ZX.farm.coinType,
					avoidMurderer = ZX.farm.avoidMurderer, afkReset = ZX.farm.afkReset,
				},
				movement = {
					speedGlitch = ZX.movement.speedGlitch, speedPower = ZX.movement.speedPower,
					speedKey = ZX.movement.speedKey and ZX.movement.speedKey.Name or nil,
				},
				aura = { whiteSpark = ZX.aura.whiteSpark, ultraInstinct = ZX.aura.ultraInstinct },
				character = { korblox = ZX.character.korblox, headless = ZX.character.headless },
				skybox = { selected = ZX.skybox.selected },
				animations = {
					Idle = ZX.animations.Idle,
					Walk = ZX.animations.Walk,
					Run = ZX.animations.Run,
					Jump = ZX.animations.Jump,
					Fall = ZX.animations.Fall,
					Swim = ZX.animations.Swim,
					SwimIdle = ZX.animations.SwimIdle,
					Climb = ZX.animations.Climb,
				},
				skins = {
					enabled = ZX.skins.enabled,
					knife = type(ZX.skins.knife) == "table" and ZX.skins.knife.key or nil,
					gun = type(ZX.skins.gun) == "table" and ZX.skins.gun.key or nil,
				},
				mapVote = { panel = ZX.mapVote.panel, count = ZX.mapVote.count },
				universalEsp = {
					enabled = ZX.universalEsp.enabled, box = ZX.universalEsp.box,
					skeleton = ZX.universalEsp.skeleton, names = ZX.universalEsp.names,
					teamCheck = ZX.universalEsp.teamCheck,
				},
				antiFling = { enabled = ZX.antiFling.enabled },
				sounds = { murdererKill = ZX.sounds.murdererKill, sheriffKill = ZX.sounds.sheriffKill, volume = ZX.sounds.volume },
				tsb = { autoBlock = ZX.tsb.autoBlock, range = ZX.tsb.range, delay = ZX.tsb.delay, fov = ZX.tsb.fov, facing = ZX.tsb.facing, aimHelper = ZX.tsb.aimHelper, blockKey = ZX.tsb.blockKey and ZX.tsb.blockKey.Name or nil, counterEsp = ZX.tsb.counterEsp, counterNotify = ZX.tsb.counterNotify, counterKey = ZX.tsb.counterKey and ZX.tsb.counterKey.Name or nil },
			}
		end

		local function applyConfig(data)
			if type(data) ~= "table" then return end
			if type(data.esp) == "table" then
				for k, v in pairs(data.esp) do ZX.esp[k] = v end
				pcall(function() uiRefs.esp_enabled:SetValue(ZX.esp.enabled) end)
				pcall(function() uiRefs.esp_box:SetValue(ZX.esp.box) end)
				pcall(function() uiRefs.esp_skeleton:SetValue(ZX.esp.skeleton) end)
				pcall(function() uiRefs.esp_names:SetValue(ZX.esp.names) end)
				pcall(function() uiRefs.esp_murderer:SetValue(ZX.esp.murderer) end)
				pcall(function() uiRefs.esp_sheriff:SetValue(ZX.esp.sheriff) end)
				pcall(function() uiRefs.esp_innocent:SetValue(ZX.esp.innocent) end)
			end
			if type(data.hitbox) == "table" then
				ZX.hitbox.enabled = data.hitbox.enabled == true
				ZX.hitbox.size = tonumber(data.hitbox.size) or 15
				ZX.hitbox.transparency = tonumber(data.hitbox.transparency) or 0.5
				pcall(function() uiRefs.hitbox_enabled:SetValue(ZX.hitbox.enabled) end)
				pcall(function() uiRefs.hitbox_size:SetValue(ZX.hitbox.size) end)
				pcall(function() uiRefs.hitbox_trans:SetValue(math.floor(ZX.hitbox.transparency * 100)) end)
				pcall(updateAllHitboxes)
			end
			if type(data.combat) == "table" then
				ZX.combat.wallbang = data.combat.wallbang ~= false
				ZX.combat.autoGrabGun = data.combat.autoGrabGun == true
				ZX.combat.shootKey = (type(data.combat.shootKey) == "string" and Enum.KeyCode[data.combat.shootKey]) or nil
				pcall(function() uiRefs.combat_wallbang:SetValue(ZX.combat.wallbang) end)
				pcall(function() uiRefs.combat_autoGrab:SetValue(ZX.combat.autoGrabGun) end)
				pcall(function() uiRefs.combat_shootKey:SetValue(ZX.combat.shootKey and ZX.combat.shootKey.Name or nil) end)
				ZX.combat.killAura = data.combat.killAura == true
				ZX.combat.spinbot = data.combat.spinbot == true
				ZX.combat.spinSpeed = tonumber(data.combat.spinSpeed) or 50
				pcall(function() uiRefs.combat_killAura:SetValue(ZX.combat.killAura) end)
				pcall(function() uiRefs.combat_spinbot:SetValue(ZX.combat.spinbot) end)
				ZX.combat.revealRoles = data.combat.revealRoles == true
				pcall(function() uiRefs.combat_spinSpeed:SetValue(ZX.combat.spinSpeed) end)
				pcall(function() uiRefs.combat_revealRoles:SetValue(ZX.combat.revealRoles) end)
			end
			if type(data.farm) == "table" then
				ZX.farm.enabled = data.farm.enabled == true
				if type(data.farm.mode) == "string" then ZX.farm.mode = data.farm.mode end
				ZX.farm.speed = tonumber(data.farm.speed) or 23
				ZX.farm.delay = tonumber(data.farm.delay) or 0.1
				pcall(function() uiRefs.farm_enabled:SetValue(ZX.farm.enabled) end)
				pcall(function() uiRefs.farm_mode:SetValue(ZX.farm.mode) end)
				pcall(function() uiRefs.farm_speed:SetValue(ZX.farm.speed) end)
				pcall(function() uiRefs.farm_delay:SetValue(math.floor(ZX.farm.delay * 100)) end)
			end
			if type(data.movement) == "table" then
				ZX.movement.speedGlitch = data.movement.speedGlitch == true
				ZX.movement.speedPower = tonumber(data.movement.speedPower) or 38
				ZX.movement.speedKey = (type(data.movement.speedKey) == "string" and Enum.KeyCode[data.movement.speedKey]) or nil
				pcall(function() uiRefs.move_speedGlitch:SetValue(ZX.movement.speedGlitch) end)
				pcall(function() uiRefs.move_speedPower:SetValue(ZX.movement.speedPower) end)
				pcall(function() uiRefs.move_speedKey:SetValue(ZX.movement.speedKey and ZX.movement.speedKey.Name or nil) end)
			end
			if type(data.character) == "table" then
				ZX.character.korblox = data.character.korblox == true
				ZX.character.headless = data.character.headless == true
				pcall(applyKorblox, ZX.character.korblox)
				pcall(applyHeadless, ZX.character.headless)
				pcall(function() uiRefs.char_korblox:SetValue(ZX.character.korblox) end)
				pcall(function() uiRefs.char_headless:SetValue(ZX.character.headless) end)
			end
			if type(data.skybox) == "table" and type(data.skybox.selected) == "string" then
				ZX.skybox.selected = data.skybox.selected
				pcall(ApplySkybox, ZX.skybox.selected)
				pcall(function() if uiRefs.skybox_select and uiRefs.skybox_select.SetValue then uiRefs.skybox_select:SetValue(ZX.skybox.selected) end end)
			end
			if type(data.animations) == "table" then
				for _, cat in ipairs(GAZER_ANIM_CATS) do
					local v = data.animations[cat]
					if type(v) == "string" then
						ZX.animations[cat] = v
						pcall(ApplyFEAnimation, cat, v)
						pcall(function()
							local r = uiRefs["anim_" .. cat]
							if r and r.SetValue then r:SetValue(v) end
						end)
					end
				end
			end
			if type(data.aura) == "table" then
				ZX.aura.whiteSpark = data.aura.whiteSpark == true
				ZX.aura.ultraInstinct = data.aura.ultraInstinct == true
				pcall(applyAuras)
				pcall(function() uiRefs.aura_whiteSpark:SetValue(ZX.aura.whiteSpark) end)
				pcall(function() uiRefs.aura_ultraInstinct:SetValue(ZX.aura.ultraInstinct) end)
			end
			if type(data.skins) == "table" then
				ZX.skins.enabled = data.skins.enabled == true
				local kKey = type(data.skins.knife) == "string" and data.skins.knife or (type(data.skins.knife) == "table" and data.skins.knife.key or nil)
				local gKey = type(data.skins.gun) == "string" and data.skins.gun or (type(data.skins.gun) == "table" and data.skins.gun.key or nil)
				local kEntry = kKey and skinCatalogData.ByKey[kKey] or (type(data.skins.knife) == "table" and data.skins.knife or nil)
				local gEntry = gKey and skinCatalogData.ByKey[gKey] or (type(data.skins.gun) == "table" and data.skins.gun or nil)
				ZX.skins.knife = kEntry
				ZX.skins.gun = gEntry
				pcall(function() uiRefs.skins_enabled_k:SetValue(ZX.skins.enabled) end)
				pcall(function() uiRefs.skins_enabled_g:SetValue(ZX.skins.enabled) end)
				if ZX.skins.enabled then
					if kEntry then pcall(applyWeaponSkin, "Knife", kEntry) end
					if gEntry then pcall(applyWeaponSkin, "Gun", gEntry) end
				else
					pcall(applyWeaponSkin, "Knife", nil)
					pcall(applyWeaponSkin, "Gun", nil)
					ZX.skins.knife = kEntry
					ZX.skins.gun = gEntry
				end
			end
			if type(data.mapVote) == "table" then
				ZX.mapVote.panel = true
				ZX.mapVote.count = tonumber(data.mapVote.count) or 10
			end
			if type(data.universalEsp) == "table" then
				for k, v in pairs(data.universalEsp) do ZX.universalEsp[k] = v end
				pcall(function() uiRefs.uni_enabled:SetValue(ZX.universalEsp.enabled) end)
				pcall(function() uiRefs.uni_box:SetValue(ZX.universalEsp.box) end)
				pcall(function() uiRefs.uni_skeleton:SetValue(ZX.universalEsp.skeleton) end)
				pcall(function() uiRefs.uni_names:SetValue(ZX.universalEsp.names) end)
				pcall(function() uiRefs.uni_teamCheck:SetValue(ZX.universalEsp.teamCheck) end)
			end
			if type(data.tsb) == "table" then
				ZX.tsb.autoBlock = data.tsb.autoBlock == true
				ZX.tsb.range = tonumber(data.tsb.range) or 25
				ZX.tsb.delay = tonumber(data.tsb.delay) or 0
				ZX.tsb.fov = tonumber(data.tsb.fov) or 180
				ZX.tsb.facing = data.tsb.facing == true
				ZX.tsb.aimHelper = data.tsb.aimHelper == true
				ZX.tsb.counterEsp = data.tsb.counterEsp == true
				ZX.tsb.counterNotify = data.tsb.counterNotify ~= false
				ZX.tsb.blockKey = (type(data.tsb.blockKey) == "string" and Enum.KeyCode[data.tsb.blockKey]) or nil
				ZX.tsb.counterKey = (type(data.tsb.counterKey) == "string" and Enum.KeyCode[data.tsb.counterKey]) or nil
				pcall(function() uiRefs.tsb_blockKey:SetValue(ZX.tsb.blockKey and ZX.tsb.blockKey.Name or nil) end)
				pcall(function() uiRefs.tsb_counterKey:SetValue(ZX.tsb.counterKey and ZX.tsb.counterKey.Name or nil) end)
				pcall(function() uiRefs.tsb_autoBlock:SetValue(ZX.tsb.autoBlock) end)
				pcall(function() uiRefs.tsb_range:SetValue(ZX.tsb.range) end)
				pcall(function() uiRefs.tsb_delay:SetValue(math.floor(ZX.tsb.delay * 1000)) end)
				pcall(function() uiRefs.tsb_fov:SetValue(ZX.tsb.fov) end)
				pcall(function() uiRefs.tsb_facing:SetValue(ZX.tsb.facing) end)
				pcall(function() uiRefs.tsb_aimHelper:SetValue(ZX.tsb.aimHelper) end)
				pcall(function() uiRefs.tsb_counterEsp:SetValue(ZX.tsb.counterEsp) end)
				pcall(function() uiRefs.tsb_counterNotify:SetValue(ZX.tsb.counterNotify) end)
			end
			if type(data.sounds) == "table" then
				if type(data.sounds.murdererKill) == "string" then ZX.sounds.murdererKill = data.sounds.murdererKill end
				if type(data.sounds.sheriffKill) == "string" then ZX.sounds.sheriffKill = data.sounds.sheriffKill end
				ZX.sounds.volume = tonumber(data.sounds.volume) or 80
				pcall(function() uiRefs.sounds_murderer:SetValue(ZX.sounds.murdererKill) end)
				pcall(function() uiRefs.sounds_sheriff:SetValue(ZX.sounds.sheriffKill) end)
				pcall(function() uiRefs.sounds_volume:SetValue(ZX.sounds.volume) end)
			end
			if type(data.antiFling) == "table" then
				ZX.antiFling.enabled = data.antiFling.enabled == true
				pcall(function() uiRefs.antiFling_enabled:SetValue(ZX.antiFling.enabled) end)
			end
		end

		local cfgSec = SettingsGroup.Config:AddSection({ Name = "Config Manager", Position = "left" })
		cfgSec:AddLabel("Config Name"):AddTextInput({
			Default = "default",
			Placeholder = "Config adı yaz...",
			Callback = function(txt)
				typedName = sanitizeName(txt)
			end,
		})
		local cfgDropdown = cfgSec:AddLabel("Saved Configs"):AddDropdown({
			Values = listSavedConfigs(),
			Default = "default",
			Callback = function(val)
				selectedConfig = sanitizeName(val)
			end,
		})

		local cfgActSec = SettingsGroup.Config:AddSection({ Name = "Actions", Position = "right" })
		cfgActSec:AddButton({
			Name = "Save Config",
			Callback = function()
				if type(writefile) ~= "function" then return end
				ensureDir()
				local name = sanitizeName(typedName)
				local json = HttpService:JSONEncode(collectConfig())
				pcall(writefile, CFG_DIR .. "/" .. name .. ".json", json)
				local idx = readConfigIndex()
				local exists = false
				for _, v in ipairs(idx) do if v == name then exists = true break end end
				if not exists then table.insert(idx, name); writeConfigIndex(idx) end
				selectedConfig = name
				pcall(function() cfgDropdown:SetValues(listSavedConfigs()) end)
				pcall(function() cfgDropdown:SetValue(name) end)
			end,
		})
		cfgActSec:AddButton({
			Name = "Load Config",
			Callback = function()
				local name = sanitizeName(selectedConfig)
				if loaderData and type(loaderData.configs) == "table" and type(loaderData.configs[name]) == "table" then
					applyConfig(loaderData.configs[name])
					return
				end
				if type(readfile) ~= "function" then return end
				local ok, raw = pcall(readfile, CFG_DIR .. "/" .. name .. ".json")
				if ok and type(raw) == "string" then
					local okJ, tbl = pcall(function() return HttpService:JSONDecode(raw) end)
					if okJ then applyConfig(tbl) end
				end
			end,
		})
		cfgActSec:AddButton({
			Name = "Delete Config",
			Callback = function()
				local name = sanitizeName(selectedConfig)
				if type(delfile) == "function" then
					pcall(delfile, CFG_DIR .. "/" .. name .. ".json")
				end
				local idx = {}
				for _, v in ipairs(readConfigIndex()) do
					if v ~= name then table.insert(idx, v) end
				end
				writeConfigIndex(idx)
				local list = listSavedConfigs()
				selectedConfig = list[1] or "default"
				pcall(function() cfgDropdown:SetValues(list) end)
				pcall(function() cfgDropdown:SetValue(selectedConfig) end)
			end,
		})
	end

	-- Shoot Murderer & Speed Glitch Tuş Dinleyicisi
	UserInputService.InputBegan:Connect(function(input, gp)
		if gp then return end
		if ZX.combat.shootKey and input.KeyCode == ZX.combat.shootKey then
			pcall(triggerShootMurderer)
		elseif ZX.tsb.blockKey and input.KeyCode == ZX.tsb.blockKey then
			ZX.tsb.autoBlock = not ZX.tsb.autoBlock
			pcall(function() uiRefs.tsb_autoBlock:SetValue(ZX.tsb.autoBlock) end)
		elseif ZX.tsb.counterKey and input.KeyCode == ZX.tsb.counterKey then
			ZX.tsb.counterEsp = not ZX.tsb.counterEsp
			pcall(function() uiRefs.tsb_counterEsp:SetValue(ZX.tsb.counterEsp) end)
		elseif ZX.movement.speedKey and input.KeyCode == ZX.movement.speedKey then
			ZX.movement.speedGlitch = not ZX.movement.speedGlitch
			pcall(function() uiRefs.move_speedGlitch:SetValue(ZX.movement.speedGlitch) end)
		end
	end)

	-- PC: RightShift ESİR ALMA (ShiftLock'ı tamamen sadece LeftShift'e bırakır, RightShift sadece menüyü açar/kapar)
	pcall(function()
		local ps = player:FindFirstChild("PlayerScripts")
		local pm = ps and ps:FindFirstChild("PlayerModule")
		local cm = pm and pm:FindFirstChild("CameraModule")
		local ml = cm and cm:FindFirstChild("MouseLockController")
		local bk = ml and ml:FindFirstChild("BoundKeys")
		if bk and bk:IsA("StringValue") then
			bk.Value = "LeftShift"
		end
	end)

	ContextActionService:BindActionAtPriority("CelestialHub_RShiftTrap", function(_, state)
		if state == Enum.UserInputState.Begin then
			pcall(function() Window:ToggleInterface() end)
		end
		return Enum.ContextActionResult.Sink
	end, false, Enum.ContextActionPriority.High.Value + 5000, Enum.KeyCode.RightShift)

end
